code.java:
class Solution {
    public int bitwiseComplement(int n){
        if(n==0)return 1;
        int mask=0;
        for(int copy=n;copy>0;copy>>=1)mask=(mask<<1)|1;
        return n^mask;
    }
}

code.kotlin:
class Solution {
    fun bitwiseComplement(n:Int):Int{
        if(n==0)return 1;
        var mask=0;
        var copy=n;
        while(copy>0){
            mask=(mask shl 1) or 1;
            copy=copy shr 1
        };
        return n xor mask
    }
}

